const getModeratorsList = (): string[] => {
  try {
    const staff = AstrxySyncEngine.getSynchronizedStaff()
    if (Array.isArray(staff) && staff.length > 0) {
      return staff.map((s) => s.email.toLowerCase().trim())
    }
    const raw = safeStorage.getItem("ast_moderators")
    if (raw) {
      const parsed = JSON.parse(raw)
      if (Array.isArray(parsed)) {
        return parsed.map((e: string) => e.toLowerCase().trim())
      }
    }
  } catch {}
  return DEFAULT_MODERATORS
}

const saveModeratorsList = (list: string[]) => {
  safeStorage.setItem("ast_moderators", JSON.stringify(list.map((e) => e.toLowerCase().trim())))
}

const isModeratorAccount = (email: string): boolean => {
  if (!email) return false
  const list = getModeratorsList()
  return list.includes(email.toLowerCase().trim())
}

class AdminOutputBoundary extends Component<{ children: React.ReactNode }, { failed: boolean }> {
  state = { failed: false }
  static getDerivedStateFromError() {
    return { failed: true }
  }
  render() {
    if (this.state.failed) {
      return <div className="admin-command-result" role="alert">Unable to render output safely.</div>
    }
    return this.props.children
  }
}

