const isNetflixMessage = (msg: Message): boolean => {
  if (!msg) return false
  const combined = `${msg.sender} ${msg.senderName || ""} ${msg.subject} ${msg.body || ""}`.toLowerCase()
  return combined.includes("netflix") || msg.sender.toLowerCase().includes("account.netflix.com")
}

