const isClaudeMessage = (msg: Message): boolean => {
  if (!msg) return false
  const combined = `${msg.sender} ${msg.senderName || ""} ${msg.subject} ${msg.body || ""}`.toLowerCase()
  return (
    combined.includes("claude") ||
    combined.includes("anthropic") ||
    msg.sender.toLowerCase().includes("mail.anthropic.com")
  )
}

