const SenderAvatar = ({
  sender,
  senderName,
  size = 32,
  className = "",
}: {
  sender: string
  senderName?: string
  size?: number
  className?: string
}) => {
  const [imgFailed, setImgFailed] = useState(false)
  const displayName = cleanSenderDisplay(sender, senderName)
  const initial = (displayName.trim().charAt(0) || "?").toUpperCase()
  const faviconUrl = getSenderFaviconUrl(sender)
  const bgColor = avatarColorFor(displayName)

  if (faviconUrl && !imgFailed) {
    return (
      <div
        className={`sender-favicon-container ${className}`}
        style={{
          width: `${size}px`,
          height: `${size}px`,
          minWidth: `${size}px`,
          borderRadius: "50%",
          background: "#ffffff",
          border: "1px solid rgba(0, 0, 0, 0.08)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
          boxShadow: "0 1px 3px rgba(0,0,0,0.12)",
          flexShrink: 0,
        }}
        title={displayName}
      >
        <img
          src={faviconUrl}
          alt={displayName}
          width={Math.round(size * 0.65)}
          height={Math.round(size * 0.65)}
          style={{
            objectFit: "contain",
            borderRadius: "2px",
          }}
          onError={() => setImgFailed(true)}
          loading="lazy"
        />
      </div>
    )
  }

  return (
    <div
      className={`gmail-avatar ${className}`}
      style={{
        width: `${size}px`,
        height: `${size}px`,
        minWidth: `${size}px`,
        background: `linear-gradient(135deg, ${bgColor}, #1e293b)`,
        borderRadius: "50%",
        color: "#ffffff",
        fontWeight: 700,
        fontSize: size >= 36 ? "0.95rem" : "0.75rem",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        boxShadow: "0 2px 5px rgba(0,0,0,0.2)",
        flexShrink: 0,
      }}
      title={displayName}
    >
      {initial}
    </div>
  )
}

