  // Track the message ID for which OTP was already auto-copied
  const lastCopiedOtpIdRef = useRef<string | null>(null)

  const [saved, setSaved] = useState<SavedEmail[]>(() => {
    try {
      if (typeof window !== "undefined") {
        const stored = safeStorage.getItem("astrxy_saved_emails")
        if (stored) {
          const parsed = JSON.parse(stored)
          if (Array.isArray(parsed)) return parsed
        }
      }
    } catch {}
    return []
  })

  // Computed: check if the currently active mailbox is already in saved list
  const isCurrentEmailSaved = useMemo(() => {
    if (!activeEmail || !Array.isArray(saved)) return false
    return saved.some((i) => i.address.toLowerCase() === activeEmail.toLowerCase())
  }, [saved, activeEmail])

  // 📁 Open and Switch to Saved Mailbox with Instant Scroll & Refresh
  const openSavedMailbox = (item: SavedEmail) => {
    const email = item.address.toLowerCase().trim()
    const isMaster = email === "astrxy@beezelbub.com"
    setActiveEmail(item.address)
    setSecretKey(item.key || "")
    safeStorage.setItem("ast_active_mailbox", item.address)
    safeStorage.setItem("astrxy_active_email", item.address)
    if (item.key) {
      safeStorage.setItem("ast_secret_key", item.key)
      safeStorage.setItem(`astrxy_mailbox_key_${item.address}`, item.key)
    }

    // Check if ACTUALLY claimed (locally or on real server)
    const claims = readClaimedKeys()
    const isLocalClaimed = isMaster || Object.values(claims).some((c) => c.toLowerCase() === email)
    if (isLocalClaimed) {
      setClaimed(true)
      setClaimedAddress(item.address)
      setClaimedKey(item.key || "")
    } else {
      setClaimed(false)
      setClaimedAddress("")
      setClaimedKey("")
      void isClaimedOnServer(email).then((serverClaimed) => {
        if (serverClaimed) {
          setClaimed(true)
          setClaimedAddress(item.address)
          setClaimedKey(item.key || "")
        }
      })
    }

    try {
      const cached = safeStorage.getItem(`ast_inbox_${email}`)
      if (cached) {
        const parsed = JSON.parse(cached)
        if (Array.isArray(parsed) && parsed.length > 0) setMessages(parsed)
        else setMessages([])
      } else {
        setMessages([])
      }
    } catch {
      setMessages([])
    }
    lastCopiedOtpIdRef.current = null
    void fetchReferralCount(item.address)
    void checkLiveVipStatus(item.address)
    setShowSavedEmailsModal(false)
    toast.success(`Mailbox opened: ${item.address}`)

    setTimeout(() => {
      document.querySelector(".messages-card")?.scrollIntoView({ behavior: "smooth", block: "start" })
      refreshMessagesRef.current?.()
    }, 120)
  }
  const [restoreKey, setRestoreKey] = useState("")
  const [isRefreshing, setIsRefreshing] = useState(false)
