  // Live Animated Display Name Engine (Discord Nitro FX & Moving Shimmer Gradients)
  const renderLiveCallsign = (
    rawCallsign: string,
    defaultColor: string,
    options?: { isMe?: boolean; roleColor?: string; onClick?: () => void; title?: string }
  ) => {
    let animType = ""
    let cleanName = rawCallsign
    const animMatch = rawCallsign.match(/^\[anim:([a-z]+)\]\s*(.*)$/i)
    if (animMatch) {
      animType = animMatch[1].toLowerCase()
      cleanName = animMatch[2]
    } else {
      const lower = rawCallsign.toLowerCase()
      if (lower.includes("anime") || lower.includes("manga") || lower.includes("chan") || lower.includes("kun") || lower.includes("san") || lower.includes("senpai") || lower.includes("sama") || lower.includes("shinigami") || lower.includes("ninja") || lower.includes("hokage") || lower.includes("titan") || lower.includes("ghoul") || lower.includes("saiyan")) {
        animType = "anime"
      } else if (lower.includes("wave") || lower.includes("ocean") || lower.includes("sea") || lower.includes("water") || lower.includes("tide")) {
        animType = "wave"
      } else if (lower.includes("flame") || lower.includes("fire") || lower.includes("blaze") || lower.includes("burn") || lower.includes("infernal")) {
        animType = "flame"
      } else if (lower.includes("cosmic") || lower.includes("void") || lower.includes("abyss") || lower.includes("astral")) {
        animType = "cosmic"
      } else if (lower.includes("gold") || lower.includes("king") || lower.includes("founder") || lower.includes("joyboy") || lower.includes("sovereign")) {
        animType = "gold"
      } else if (lower.includes("cyber") || lower.includes("lightning") || lower.includes("storm") || lower.includes("volt")) {
        animType = "cyber"
      } else if (lower.includes("diamond") || lower.includes("ice") || lower.includes("frost") || lower.includes("crystal")) {
        animType = "diamond"
      } else if (lower.length > 0 && !lower.startsWith("visitor") && !lower.startsWith("guest") && lower !== "navigator") {
        animType = "anime"
      }
    }

    if (!animType) {
      return (
        <span
          style={{
            fontWeight: 700,
            color: defaultColor,
            cursor: "pointer",
            textDecoration: "underline dotted",
          }}
          onClick={options?.onClick}
          title={options?.title}
        >
          {cleanName}
        </span>
      )
    }

    const animConfigs: Record<string, { gradient: string; badge: string; glow: string; speed: string }> = {
      anime: {
        gradient: "linear-gradient(90deg, #ec4899, #8b5cf6, #3b82f6, #06b6d4, #10b981, #f59e0b, #ec4899)",
        badge: "✨",
        glow: "rgba(168, 85, 247, 0.75)",
        speed: "2.4s",
      },
      rainbow: {
        gradient: "linear-gradient(90deg, #ff007f, #a855f7, #06b6d4, #10b981, #f59e0b, #ff007f)",
        badge: "🌈",
        glow: "rgba(236, 72, 153, 0.55)",
        speed: "3s",
      },
      flame: {
        gradient: "linear-gradient(90deg, #ef4444, #f97316, #fbbf24, #f97316, #ef4444)",
        badge: "🔥",
        glow: "rgba(239, 68, 68, 0.6)",
        speed: "2.2s",
      },
      cyber: {
        gradient: "linear-gradient(90deg, #06b6d4, #8b5cf6, #ec4899, #8b5cf6, #06b6d4)",
        badge: "⚡",
        glow: "rgba(6, 182, 212, 0.6)",
        speed: "2s",
      },
      diamond: {
        gradient: "linear-gradient(90deg, #f0f9ff, #38bdf8, #818cf8, #c084fc, #38bdf8, #f0f9ff)",
        badge: "💎",
        glow: "rgba(56, 189, 248, 0.65)",
        speed: "2.6s",
      },
      gold: {
        gradient: "linear-gradient(90deg, #fef08a, #f59e0b, #b45309, #fbbf24, #fef08a)",
        badge: "👑",
        glow: "rgba(245, 158, 11, 0.6)",
        speed: "2.8s",
      },
      wave: {
        gradient: "linear-gradient(90deg, #0284c7, #06b6d4, #34d399, #06b6d4, #0284c7)",
        badge: "🌊",
        glow: "rgba(14, 165, 233, 0.6)",
        speed: "3.2s",
      },
      cosmic: {
        gradient: "linear-gradient(90deg, #c084fc, #e879f9, #f43f5e, #a855f7, #c084fc)",
        badge: "🌌",
        glow: "rgba(192, 132, 252, 0.6)",
        speed: "3s",
      },
    }

    const conf = animConfigs[animType] || animConfigs.rainbow

    return (
      <span
        onClick={options?.onClick}
        title={options?.title || `Live Moving Callsign [${animType.toUpperCase()}]`}
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: "3px",
          cursor: "pointer",
          fontWeight: 800,
          letterSpacing: "0.2px",
        }}
      >
        <span
          style={{
            display: "inline-block",
            animation: "astrxyFloatSparkle 2s ease-in-out infinite",
            fontSize: "10px",
          }}
        >
          {conf.badge}
        </span>
        <span
          style={{
            background: conf.gradient,
            backgroundSize: "300% 100%",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            animation: `astrxyMovingGradient ${conf.speed} linear infinite`,
            filter: `drop-shadow(0 0 4px ${conf.glow})`,
            textDecoration: "none",
          }}
        >
          {cleanName}
        </span>
      </span>
    )
  }
  const [customNicknameInput, setCustomNicknameInput] = useState<string>("")

