  // Account-Scoped Progress Storage (Prevents progress leaking when users log out or switch)
  const getTowerUserKey = (email?: string | null) => {
    const clean = (email || "").trim().toLowerCase()
    return clean ? `ast_tower_save_v4_${clean}` : "ast_tower_save_v4_guest"
  }

  const loadTowerSaveForUser = (email?: string | null) => {
    if (typeof window !== "undefined") {
      try {
        const k = getTowerUserKey(email)
        const raw = safeStorage.getItem(k)
        if (raw) {
          const parsed = JSON.parse(raw)
          if (parsed && typeof parsed === "object") return parsed
        }
      } catch {}
    }
    return null
  }

  const currentEmailKey = (chatClaimedEmail || activeEmail || "guest").toLowerCase().trim()
  const initialSave = loadTowerSaveForUser(currentEmailKey)

