  const [towerGold, setTowerGold] = useState<number>(initialSave?.towerGold || 150)
  // Universal currency and number formatter safe for all rooms & views
  const formatUniversalCurrency = (num: number): string => {
    if (!num || isNaN(num)) return "0"
    if (num >= 1000000000) return `${(num / 1000000000).toFixed(num % 1000000000 === 0 ? 0 : 1)}B`
    if (num >= 1000000) return `${(num / 1000000).toFixed(num % 1000000 === 0 ? 0 : 1)}M`
    if (num >= 1000) return `${(num / 1000).toFixed(num % 1000 === 0 ? 0 : 1)}K`
    return Math.round(num).toLocaleString()
  }
  const [towerSoulEssence, setTowerSoulEssence] = useState<number>(initialSave?.towerSoulEssence || 300)
  const [towerPlayerHp, setTowerPlayerHp] = useState<number>(initialSave?.towerPlayerHp || 800)
  const [towerPlayerMaxHp, setTowerPlayerMaxHp] = useState<number>(initialSave?.towerPlayerMaxHp || 800)
  const [towerPlayerAtk, setTowerPlayerAtk] = useState<number>(initialSave?.towerPlayerAtk || 65)
  const [towerPlayerDef, setTowerPlayerDef] = useState<number>(initialSave?.towerPlayerDef || 40)
  const [towerSkills, setTowerSkills] = useState<TowerSkill[]>(initialSave?.towerSkills || defaultSkills)
  const [towerEquipped, setTowerEquipped] = useState<TowerEquippedGear>(initialSave?.towerEquipped || {
    weapon: null,
    armor: null,
    boots: null,
  })
  const [towerInventory, setTowerInventory] = useState<TowerGearItem[]>(initialSave?.towerInventory || [])
  const [towerAngelArmorActive, setTowerAngelArmorActive] = useState<boolean>(initialSave?.towerAngelArmorActive || false)
  const [towerAngelArmorHp, setTowerAngelArmorHp] = useState<number>(initialSave?.towerAngelArmorHp || 0)
  const [towerInCombat, setTowerInCombat] = useState<boolean>(false)
  const [towerCurrentEnemy, setTowerCurrentEnemy] = useState<TowerEnemy | null>(null)
  const [towerIsResting, setTowerIsResting] = useState<boolean>(false)
  const [towerRestSeconds, setTowerRestSeconds] = useState<number>(0)
  const [towerHiddenQuests, setTowerHiddenQuests] = useState<Record<number, boolean>>(initialSave?.towerHiddenQuests || {})
  const [towerCombatLogs, setTowerCombatLogs] = useState<string[]>([
    "⚔️ Tower of Trials initialized. Choose class, challenge bosses every 10 floors, equip gear, and conquer Floor 100!"
  ])
  const [towerActiveView, setTowerActiveView] = useState<"arena" | "skills" | "equipment" | "shop" | "leaderboard" | "quests" | "classes" | "pvp" | "forge" | "gauntlet" | "raid" | "bestiary" | "achievements" | "fishing" | "crew">("arena")
  // Live Visual Battle Animation Engine
  const [combatAnimState, setCombatAnimState] = useState<"idle" | "player_attack" | "player_cast" | "enemy_hit" | "enemy_attack" | "player_hit" | "player_dodge">("idle")
  const [combatFloatingNums, setCombatFloatingNums] = useState<Array<{ id: string; text: string; isCrit?: boolean; isHeal?: boolean; isPlayer?: boolean }>>([])
  const [combatArenaShake, setCombatArenaShake] = useState<boolean>(false)
  const [combatSpellProjectile, setCombatSpellProjectile] = useState<{ active: boolean; type?: "fire" | "frost" | "lightning" | "void" | "holy" | "dark" | "slash" | "heal" | "shield" | "cosmic"; rank?: string; name?: string } | null>(null)
  const [combatEnemySpellProjectile, setCombatEnemySpellProjectile] = useState<{ active: boolean; type?: string; name?: string } | null>(null)
  // Pet Familiar & Beast Egg State
  const [towerActivePet, setTowerActivePet] = useState<any | null>(() => {
    try {
      const saved = safeStorage.getItem("ast_tower_active_pet")
      return saved ? JSON.parse(saved) : null
    } catch { return null }
  })
  const [towerPlayerPets, setTowerPlayerPets] = useState<any[]>(() => {
    try {
      const saved = safeStorage.getItem("ast_tower_player_pets")
      return saved ? JSON.parse(saved) : []
    } catch { return [] }
  })
  const [towerPetEggs, setTowerPetEggs] = useState<{ wyrm: number; wolf: number; hawk: number }>(() => {
    try {
      const saved = safeStorage.getItem("ast_tower_pet_eggs")
      return saved ? JSON.parse(saved) : { wyrm: 1, wolf: 0, hawk: 0 }
    } catch { return { wyrm: 1, wolf: 0, hawk: 0 } }
  })
  const [towerPetFood, setTowerPetFood] = useState<number>(() => {
    try {
      const saved = safeStorage.getItem("ast_tower_pet_food")
      return saved ? parseInt(saved, 10) : 5
    } catch { return 5 }
  })
  const [petAssistNotice, setPetAssistNotice] = useState<string | null>(null)
