  // --- TYPE EFFECTIVENESS TABLE ---
  const POKEMON_TYPE_EFF: Record<string, Record<string, number>> = {
    Fire: { Grass: 2, Ice: 2, Steel: 2, Fire: 0.5, Water: 0.5, Rock: 0.5, Dragon: 0.5 },
    Water: { Fire: 2, Ground: 2, Rock: 2, Water: 0.5, Grass: 0.5, Dragon: 0.5 },
    Grass: { Water: 2, Ground: 2, Rock: 2, Fire: 0.5, Grass: 0.5, Poison: 0.5, Flying: 0.5, Dragon: 0.5, Steel: 0.5 },
    Electric: { Water: 2, Flying: 2, Electric: 0.5, Grass: 0.5, Dragon: 0.5, Ground: 0 },
    Ice: { Grass: 2, Ground: 2, Flying: 2, Dragon: 2, Fire: 0.5, Water: 0.5, Ice: 0.5, Steel: 0.5 },
    Ghost: { Ghost: 2, Psychic: 2, Dark: 0.5, Normal: 0 },
    Dragon: { Dragon: 2, Steel: 0.5 },
    Dark: { Psychic: 2, Ghost: 2, Dark: 0.5 },
    Rock: { Fire: 2, Ice: 2, Flying: 2, Bug: 2, Ground: 0.5, Steel: 0.5 },
    Steel: { Ice: 2, Rock: 2, Fairy: 2, Fire: 0.5, Water: 0.5, Electric: 0.5, Steel: 0.5 },
    Normal: { Rock: 0.5, Steel: 0.5, Ghost: 0 },
  }

  const getPokemonEffectiveness = (atkType: string, defType1: string, defType2?: string): number => {
    let mult = 1.0
    const row = POKEMON_TYPE_EFF[atkType]
    if (row) {
      if (typeof row[defType1] === "number") mult *= row[defType1]
      if (defType2 && typeof row[defType2] === "number") mult *= row[defType2]
    }
    return mult
  }

