  const triggerFloatingText = (text: string, isCrit = false, isHeal = false, isPlayer = false) => {
    const id = `pop_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`
    setCombatFloatingNums((prev) => [...prev.slice(-5), { id, text, isCrit, isHeal, isPlayer }])
    setTimeout(() => {
      setCombatFloatingNums((prev) => prev.filter((item) => item.id !== id))
    }, 1100)
  }
  // Web Audio Procedural Combat Sound Engine
  const playCombatSfx = (type: "crit" | "parry" | "barrier_break" | "skill" | "fanfare" | "boss_theme") => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
      if (!AudioCtx) return
      const ctx = new AudioCtx()
      const now = ctx.currentTime

      if (type === "crit") {
        const osc = ctx.createOscillator()
        const gain = ctx.createGain()
        osc.type = "triangle"
        osc.frequency.setValueAtTime(160, now)
        osc.frequency.exponentialRampToValueAtTime(30, now + 0.25)
        gain.gain.setValueAtTime(0.8, now)
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25)
        osc.connect(gain)
        gain.connect(ctx.destination)
        osc.start(now)
        osc.stop(now + 0.25)
      } else if (type === "parry") {
        [1800, 2400].forEach((freq) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sine"
          osc.frequency.setValueAtTime(freq, now)
          gain.gain.setValueAtTime(0.35, now)
          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18)
          osc.connect(gain)
          gain.connect(ctx.destination)
          osc.start(now)
          osc.stop(now + 0.18)
        })
      } else if (type === "barrier_break") {
        [800, 1200, 1600, 2200].forEach((freq, i) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "square"
          osc.frequency.setValueAtTime(freq, now + i * 0.025)
          gain.gain.setValueAtTime(0.2, now + i * 0.025)
          gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.025 + 0.15)
          osc.connect(gain)
          gain.connect(ctx.destination)
          osc.start(now + i * 0.025)
          osc.stop(now + i * 0.025 + 0.15)
        })
      } else if (type === "skill") {
        const notes = [523.25, 659.25, 783.99, 987.77, 1046.5]
        notes.forEach((freq, idx) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sine"
          osc.frequency.setValueAtTime(freq, now + idx * 0.045)
          gain.gain.setValueAtTime(0.25, now + idx * 0.045)
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.045 + 0.2)
          osc.connect(gain)
          gain.connect(ctx.destination)
          osc.start(now + idx * 0.045)
          osc.stop(now + idx * 0.045 + 0.2)
        })
      } else if (type === "fanfare") {
        const brass = [261.63, 329.63, 392.0, 523.25, 659.25]
        brass.forEach((freq, idx) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sawtooth"
          osc.frequency.setValueAtTime(freq, now + idx * 0.07)
          gain.gain.setValueAtTime(0.2, now + idx * 0.07)
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.07 + 0.3)
          osc.connect(gain)
          gain.connect(ctx.destination)
          osc.start(now + idx * 0.07)
          osc.stop(now + idx * 0.07 + 0.3)
        })
      } else if (type === "boss_theme") {
        const bassNotes = [110, 130.81, 146.83, 164.81]
        bassNotes.forEach((freq, idx) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sawtooth"
          osc.frequency.setValueAtTime(freq, now + idx * 0.12)
          gain.gain.setValueAtTime(0.25, now + idx * 0.12)
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.12 + 0.4)
          osc.connect(gain)
          gain.connect(ctx.destination)
          osc.start(now + idx * 0.12)
          osc.stop(now + idx * 0.12 + 0.4)
        })
      }
    } catch {}
  }

