  // Character Profile Attribute Stat Points System (ATK, DEF, DEX, STA, HP)
  const [allocatedStats, setAllocatedStats] = useState<{ atk: number; def: number; dex: number; sta: number; hp: number }>(() => {
    try {
      const saved = safeStorage.getItem("ast_tower_allocated_stats")
      if (saved) return JSON.parse(saved)
    } catch {}
    return { atk: 0, def: 0, dex: 0, sta: 0, hp: 0 }
  })
  const [unallocatedStatPoints, setUnallocatedStatPoints] = useState<number>(() => {
    try {
      const saved = safeStorage.getItem("ast_tower_stat_points")
      if (saved) return parseInt(saved, 10) || 0
    } catch {}
    return Math.max(0, 15)
  })

  const handleAllocateStatPoint = (stat: "atk" | "def" | "dex" | "sta" | "hp", amount: number = 1) => {
    if (unallocatedStatPoints < amount) {
      toast.error("No unallocated stat points available!")
      return
    }
    const nextPoints = unallocatedStatPoints - amount
    const nextStats = { ...allocatedStats, [stat]: (allocatedStats[stat] || 0) + amount }
    setUnallocatedStatPoints(nextPoints)
    setAllocatedStats(nextStats)
    safeStorage.setItem("ast_tower_stat_points", String(nextPoints))
    safeStorage.setItem("ast_tower_allocated_stats", JSON.stringify(nextStats))
    toast.success(`Allocated +${amount} point(s) to ${stat.toUpperCase()}!`)
  }

  const handleResetStatPoints = () => {
    const totalInvested = (allocatedStats.atk || 0) + (allocatedStats.def || 0) + (allocatedStats.dex || 0) + (allocatedStats.sta || 0) + (allocatedStats.hp || 0)
    if (totalInvested === 0) {
      toast.info("No stat points invested yet!")
      return
    }
    const resetCostGold = 10000
    if (towerGold < resetCostGold) {
      toast.error(`Resetting attributes requires ${resetCostGold.toLocaleString()} Gold!`)
      return
    }
    setTowerGold((g) => g - resetCostGold)
    setUnallocatedStatPoints((p) => p + totalInvested)
    const emptyStats = { atk: 0, def: 0, dex: 0, sta: 0, hp: 0 }
    setAllocatedStats(emptyStats)
    safeStorage.setItem("ast_tower_stat_points", String(unallocatedStatPoints + totalInvested))
    safeStorage.setItem("ast_tower_allocated_stats", JSON.stringify(emptyStats))
    toast.success("Attribute points successfully refunded and reset!")
  }

