  const checkClaimStatusInstant = async (emailToVerify?: string) => {
    const target = emailToVerify || activeEmail
    if (!target) return
    const isMaster = target.toLowerCase() === "astrxy@beezelbub.com"
    const claims = readClaimedKeys()
    const isLocalClaimed = isMaster || Object.values(claims).some((c) => c.toLowerCase() === target.toLowerCase())
    if (isLocalClaimed) {
      setClaimed(true)
      return
    }
    const serverClaimed = await isClaimedOnServer(target)
    setClaimed(isMaster || serverClaimed)
  }

