  const getAudioContext = (): AudioContext | null => {
    if (typeof window === "undefined") return null
    try {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
      if (!AudioCtx) return null
      if (!audioCtxRef.current || audioCtxRef.current.state === "closed") {
        audioCtxRef.current = new AudioCtx()
      }
      if (audioCtxRef.current.state === "suspended") {
        void audioCtxRef.current.resume()
      }
      return audioCtxRef.current
    } catch {
      return null
    }
  }

  const playNotificationSound = (soundChoice?: "Chime" | "Messenger" | "iOS" | "Cyber") => {
    if (!soundEnabled || typeof window === "undefined") return
    const sound = soundChoice || selectedSound || "Chime"
    try {
      const ctx = getAudioContext()
      if (!ctx) return
      if (ctx.state === "suspended") {
        void ctx.resume()
      }
      const now = ctx.currentTime

      if (sound === "iOS") {
        // Apple iOS Tri-Tone Note (D5 -> G5 -> D6 harmonic triad)
        const notes = [
          { freq: 587.33, start: 0, dur: 0.1 },
          { freq: 783.99, start: 0.1, dur: 0.1 },
          { freq: 1174.66, start: 0.2, dur: 0.4 },
        ]
        notes.forEach(({ freq, start, dur }) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sine"
          osc.frequency.setValueAtTime(freq, now + start)
          gain.gain.setValueAtTime(0.001, now + start)
          gain.gain.linearRampToValueAtTime(0.65, now + start + 0.015)
          gain.gain.exponentialRampToValueAtTime(0.001, now + start + dur)
          osc.connect(gain).connect(ctx.destination)
          osc.start(now + start)
          osc.stop(now + start + dur + 0.05)
        })
      } else if (sound === "Messenger") {
        // Facebook Messenger Inbound "Bubble Pop" Chime
        const osc1 = ctx.createOscillator()
        const gain1 = ctx.createGain()
        osc1.type = "sine"
        osc1.frequency.setValueAtTime(400, now)
        osc1.frequency.exponentialRampToValueAtTime(880, now + 0.07)
        gain1.gain.setValueAtTime(0.001, now)
        gain1.gain.linearRampToValueAtTime(0.7, now + 0.01)
        gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.08)
        osc1.connect(gain1).connect(ctx.destination)
        osc1.start(now)
        osc1.stop(now + 0.09)

        const osc2 = ctx.createOscillator()
        const gain2 = ctx.createGain()
        osc2.type = "sine"
        osc2.frequency.setValueAtTime(600, now + 0.08)
        osc2.frequency.exponentialRampToValueAtTime(1320, now + 0.18)
        gain2.gain.setValueAtTime(0.001, now + 0.08)
        gain2.gain.linearRampToValueAtTime(0.7, now + 0.095)
        gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.32)
        osc2.connect(gain2).connect(ctx.destination)
        osc2.start(now + 0.08)
        osc2.stop(now + 0.35)
      } else if (sound === "Cyber") {
        // Futuristic Sci-Fi Digital Synth Chime
        const freqs = [520, 1040, 1560, 2080]
        freqs.forEach((freq, idx) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sawtooth"
          osc.frequency.setValueAtTime(freq, now + idx * 0.05)
          gain.gain.setValueAtTime(0.001, now + idx * 0.05)
          gain.gain.linearRampToValueAtTime(0.45, now + idx * 0.05 + 0.01)
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.05 + 0.22)
          osc.connect(gain).connect(ctx.destination)
          osc.start(now + idx * 0.05)
          osc.stop(now + idx * 0.05 + 0.25)
        })
      } else {
        // Crystal Glass Bell Chime (C6 + E6 + G6 harmonic chord)
        const chord = [1046.5, 1318.51, 1567.98]
        chord.forEach((freq, idx) => {
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.type = "sine"
          osc.frequency.setValueAtTime(freq, now)
          gain.gain.setValueAtTime(0.001, now)
          gain.gain.linearRampToValueAtTime(0.55 / (idx + 1), now + 0.02)
          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.65)
          osc.connect(gain).connect(ctx.destination)
          osc.start(now)
          osc.stop(now + 0.7)
        })
      }
    } catch (err) {
      console.warn("Audio playback error:", err)
    }
  }

