  const handleNativeAudioSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (file.size > 10 * 1024 * 1024) {
      toast.error("Voice note exceeds 10MB limit.")
      if (nativeAudioInputRef.current) nativeAudioInputRef.current.value = ""
      return
    }
    const reader = new FileReader()
    reader.onloadend = () => {
      const base64Url = reader.result as string
      setVoicePreview({
        url: base64Url,
        blob: file,
        duration: 5,
      })
      toast.success("🎙️ Voice note recorded and ready to send!")
    }
    reader.onerror = () => {
      toast.error("Failed to read voice recording.")
    }
    reader.readAsDataURL(file)
    if (nativeAudioInputRef.current) nativeAudioInputRef.current.value = ""
  }

  const startVoiceRecording = async () => {
    if (isRecordingVoice) return

    // If getUserMedia is not supported (HTTP, WebView, or old browser), seamlessly open native phone voice recorder
    if (!navigator?.mediaDevices?.getUserMedia) {
      if (nativeAudioInputRef.current) {
        nativeAudioInputRef.current.click()
        toast.info("🎙️ Opening device Voice Recorder...")
        return
      }
      toast.error("Voice recording is not supported on this browser.")
      return
    }

    let stream: MediaStream | null = null
    try {
      // First attempt with standard audio constraint
      stream = await navigator.mediaDevices.getUserMedia({ audio: true })
    } catch (err: any) {
      console.warn("Direct stream mic error, activating native voice recorder fallback:", err)
      // Seamless Zero-Friction Fallback: If browser permissions blocked getUserMedia, open phone's native voice recorder!
      if (nativeAudioInputRef.current) {
        nativeAudioInputRef.current.click()
        toast.info("🎙️ Opening your phone's Voice Recorder...")
        return
      }
      toast.error("Microphone permission blocked. Tap the lock 🔒 icon in your browser address bar to allow.")
      return
    }

    try {
      // Select supported audio mime type for wide mobile compatibility (Brave, Chrome, Safari)
      let selectedMime = "audio/webm"
      if (typeof MediaRecorder !== "undefined" && typeof MediaRecorder.isTypeSupported === "function") {
        if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
          selectedMime = "audio/webm;codecs=opus"
        } else if (MediaRecorder.isTypeSupported("audio/webm")) {
          selectedMime = "audio/webm"
        } else if (MediaRecorder.isTypeSupported("audio/mp4")) {
          selectedMime = "audio/mp4"
        } else if (MediaRecorder.isTypeSupported("audio/aac")) {
          selectedMime = "audio/aac"
        } else {
          selectedMime = ""
        }
      }

      const options: MediaRecorderOptions = selectedMime ? { mimeType: selectedMime } : {}
      const mediaRecorder = new MediaRecorder(stream, options)
      mediaRecorderRef.current = mediaRecorder
      audioChunksRef.current = []

      mediaRecorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          audioChunksRef.current.push(event.data)
        }
      }

      mediaRecorder.onstop = () => {
        const mime = mediaRecorder.mimeType || selectedMime || "audio/webm"
        const audioBlob = new Blob(audioChunksRef.current, { type: mime })
        const reader = new FileReader()
        reader.onloadend = () => {
          const base64Url = reader.result as string
          setVoicePreview({
            url: base64Url,
            blob: audioBlob,
            duration: Math.max(1, Math.round((Date.now() - (recordingStartTimeRef.current || Date.now())) / 1000)),
          })
        }
        reader.readAsDataURL(audioBlob)
        stream?.getTracks().forEach((track) => track.stop())
      }

      recordingStartTimeRef.current = Date.now()
      mediaRecorder.start(250)
      setIsRecordingVoice(true)
      setRecordingSeconds(0)
      if (recordingTimerRef.current) window.clearInterval(recordingTimerRef.current)
      recordingTimerRef.current = window.setInterval(() => {
        setRecordingSeconds((prev) => prev + 1)
      }, 1000)
      toast.info("🎙️ Recording voice note... Speak now!")
    } catch (recorderErr) {
      console.warn("MediaRecorder init failed, falling back to native capture:", recorderErr)
      if (nativeAudioInputRef.current) {
        nativeAudioInputRef.current.click()
        toast.info("🎙️ Opening device Voice Recorder...")
      }
    }
  }

  const stopVoiceRecording = () => {
    if (recordingTimerRef.current) {
      window.clearInterval(recordingTimerRef.current)
      recordingTimerRef.current = null
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== "inactive") {
      mediaRecorderRef.current.stop()
    }
    setIsRecordingVoice(false)
  }

  const cancelVoiceRecording = () => {
    if (recordingTimerRef.current) {
      window.clearInterval(recordingTimerRef.current)
      recordingTimerRef.current = null
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== "inactive") {
      try { mediaRecorderRef.current.stream.getTracks().forEach((t) => t.stop()) } catch {}
      mediaRecorderRef.current.stop()
    }
    audioChunksRef.current = []
    setIsRecordingVoice(false)
    setRecordingSeconds(0)
    toast.info("Recording canceled.")
  }

