  const handleSendChatMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault()
    const text = chatInputText.trim()
    if (!text && !chatAttachment && !voicePreview) return
    if (text.length > 500) {
      toast.error("Message exceeds maximum 500 characters limit.")
      return
    }

    // Determine sender identity
    const currentActive = (activeEmail || "").toLowerCase().trim()
    const isMaster = Boolean(isUserAdmin || chatAdminUnlocked || currentActive === "astrxy@beezelbub.com")
    const isStaff = Boolean(chatStaffAuthorized )
    const senderEmail = isMaster ? "astrxy@beezelbub.com" : isStaff ? "staff@beezelbub.com" : (chatClaimedEmail || currentActive || "visitor@community.net").trim().toLowerCase()
    const senderUsername = isMaster
      ? ((chatUsername.trim() && !/^ast[a-z0-9]{5,}$/i.test(chatUsername.trim()) && chatUsername.trim() !== "Visitor") ? chatUsername.trim() : "astrxy")
      : isStaff
      ? (chatUsername.trim() || "Staff Moderator")
      : (chatUsername.trim() || "Visitor")
    const senderRole = isMaster ? "admin" : isStaff ? "moderator" : (claimed ? "claimed" : "visitor")

    // Block mention for admin only: Non-admins cannot mention JoyBoy / Admin in public chat
    if (!isMaster && !isStaff && /@(joyboy|admin|founder|shamie|astrxy) /i.test(text)) {
      toast.error("🚫 Mentioning Master Admin is disabled. Use the Inbox beside Temp Mail to message Admin.")
      return
    }

    // Mobile / Desktop Stealth Command: /admin, /gate, /ops, /vault, /joyboy
    const stealthMatch = text.match(/^\/(?:admin|gate|ops|vault|stealth|joyboy)(?:\s+(.+))?$/i)
    if (stealthMatch) {
      setChatInputText("")
      const possiblePass = (stealthMatch[1] || "").trim()
      if (possiblePass) {
        setStealthGatePasscode(possiblePass)
      }
      setShowStealthGate(true)
      toast.info("🔒 Master Stealth Gate Activated.")
      return
    }

    // In-Chat /staff demote or /demote command for Admin
    const staffCmdMatch = text.match(/^\/(?:staff|demote|removestaff|unstaff)(?:\s+(.+))?$/i)
    if (staffCmdMatch && (isMaster || isStaff || canModerate)) {
      setChatInputText("")
      const rawArgs = (staffCmdMatch[1] || "").trim()
      const parts = rawArgs.split(/\s+/)
      let targetToDemote = ""

      if (text.toLowerCase().startsWith("/demote ") || text.toLowerCase().startsWith("/removestaff ") || text.toLowerCase().startsWith("/unstaff ")) {
        targetToDemote = parts[0] || ""
      } else if (parts[0]?.toLowerCase() === "demote" || parts[0]?.toLowerCase() === "remove" || parts[0]?.toLowerCase() === "rm") {
        targetToDemote = parts[1] || ""
      } else if (parts[1]?.toLowerCase() === "demote" || parts[1]?.toLowerCase() === "remove") {
        targetToDemote = parts[0] || ""
      }

      if (targetToDemote) {
        const rawTarget = targetToDemote.toLowerCase().trim()
        const targetsToRemove = [rawTarget]
        const currentMods = getModeratorsList()
        const updated = currentMods.filter((e) => !targetsToRemove.includes(e.toLowerCase().trim()))
        saveModeratorsList(updated)
        for (const t of targetsToRemove) {
          void fetch("/api/stats", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "remove_moderator", target: t, email: t }) })
          void fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "make_staff", targetEmail: t, role: "visitor", isAdmin: true, passcode: "b3933c5b836dea05907e15eacca2ec803eaee641fb3c11b39decc19dfba3767a" }) })
        }
        toast.success(`Demoted ${rawTarget} from staff role!`)
        void fetchChatMessages(chatChannel)
        return
      }
    }

    // In-Chat /clear or /clearchat command (e.g. /clear, /clear all, /clearchat staff)
    const clearMatch = text.match(/^\/(?:clear|clearchat|purge|wipe)(?:\s+(.+))?$/i)
    if (clearMatch && (isMaster || isStaff || canModerate)) {
      setChatInputText("")
      const target = (clearMatch[1] || chatChannel).toLowerCase().trim()
      void handleClearChannelConvo(target === "all" || target === "all_rooms" || target === "everywhere" ? "all" : target)
      return
    }

    // In-Chat /room command for Master Admin
    if ((isMaster || canModerate) && text.toLowerCase().startsWith("/room ")) {
      const rawRoom = text.slice(6).trim().toLowerCase().replace(/[^a-z0-9_-]/g, "").slice(0, 24)
      if (rawRoom) {
        setChatInputText("")
        try {
          const res = await fetch("/api/chat", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ action: "create_room", roomName: rawRoom, passcode: "b3933c5b836dea05907e15eacca2ec803eaee641fb3c11b39decc19dfba3767a", isAdmin: true }),
          })
          const d = (await res.json().catch(() => ({}))) as { success?: boolean; error?: string }
          if (res.ok && d.success) {
            setChatCustomRooms((prev) => Array.from(new Set([...prev, rawRoom])))
            setChatChannel(rawRoom)
            toast.success(`Created and joined room #${rawRoom}!`)
            void fetchChatMessages(rawRoom)
          } else {
            toast.error(d.error || "Failed to create room.")
          }
        } catch { toast.error("Error creating room.") }
        return
      }
    }

    if (editingMessage) {
      const targetId = editingMessage.id
      setChatMessages((prev) =>
        prev.map((m) => (m.id === targetId ? { ...m, text, edited: true, editedAt: Date.now() } : m))
      )
      setEditingMessage(null)
      setChatInputText("")
      playNotificationSound("Messenger")

      try {
        const res = await fetch("/api/chat", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            action: "edit_msg",
            messageId: targetId,
            channel: chatChannel,
            email: senderEmail,
            username: senderUsername,
            text,
          }),
        })
        const data = (await res.json().catch(() => ({}))) as { success?: boolean; error?: string }
        if (res.ok && data.success) {
          toast.success("Message edited.")
          void fetchChatMessages(chatChannel)
        } else {
          toast.error(data.error || "Failed to edit message.")
          void fetchChatMessages(chatChannel)
        }
      } catch {}
      return
    }

    // In-Chat /necro or /necromancer command to unlock Necromancer & Angel Armor directly
    const necroCmdMatch = text.match(/^\/(?:necro|necromancer)(?:\s+(.+))?$/i)
    if (necroCmdMatch) {
      setChatInputText("")
      const possiblePass = (necroCmdMatch[1] || "").trim()
      let authorized = isMaster
      if (!authorized && (possiblePass.trim() === "b3933c5b836dea05907e15eacca2ec803eaee641fb3c11b39decc19dfba3767a")) {
        setChatAdminUnlocked(true)
        safeStorage.setItem("ast_chat_admin_unlocked", "true")
        setIsSecretLoverAuthorized(true)
        setChatStaffAuthorized(true)
        authorized = true
      }
      if (authorized) {
        handleSelectTowerClass("admin_necromancer")
        setChatChannel("tower")
        toast.success("👑 Necromancer Sovereign Activated! [Summon: Angel Armor Lvl 100] equipped!")
      } else {
        toast.error("🚫 Sovereign Necromancer is restricted to Master Admin.")
      }
      return
    }

    // Secret Admin Unlock Command via Chat (/admin <passcode>, /login <passcode>, /unlock <passcode>)
    const adminCmdMatch = text.match(/^\/(?:admin|login|unlock)\s+(.+)$/i)
    if (adminCmdMatch) {
      const candidateKey = adminCmdMatch[1].trim()
      const auth = await verifyAdminCredentials(candidateKey)
      if (auth.success && auth.isMaster) {
        setChatInputText("")
        setChatAdminUnlocked(true)
        safeStorage.setItem("ast_chat_admin_unlocked", "true")
        setChatStaffAuthorized(true)
        setIsSecretLoverAuthorized(true)

        const adminEmail = "astrxy@beezelbub.com"
        safeStorage.setItem("is_admin", "true")
        safeStorage.setItem("ast_is_owner", "true")
        safeStorage.setItem("ast_active_mailbox", adminEmail)
        safeStorage.setItem("astrxy_active_email", adminEmail)
        safeStorage.setItem("ast_chat_email", adminEmail)
        safeStorage.setItem("ast_chat_username", "astrxy")
        setActiveEmail(adminEmail)
        setClaimed(true)
        setClaimedAddress(adminEmail)
        setVipIsAdmin(true)
        setVipActive(true)
        setChatUsername("astrxy")
        setChatClaimedEmail(adminEmail)
        toast.success("👑 Master Admin Unlocked & Switched to astrxy@beezelbub.com!")
        void fetchChatMessages(chatChannel)
        return
      }
    }

    setChatLoading(true)
    try {
      let attachmentToSend = chatAttachment
      if (voicePreview) {
        attachmentToSend = {
          name: `Voice Note (${voicePreview.duration}s).webm`,
          type: "audio/webm",
          url: voicePreview.url,
          size: voicePreview.blob.size,
        }
        discardVoicePreview()
      }

      const isPublicRoom = chatChannel === "visitor" || chatChannel === "public" || !chatChannel
      const canUploadInPublic = isMaster || isStaff || isUserAdmin || chatAdminUnlocked || canModerate || chatStaffAuthorized
      if (attachmentToSend && isPublicRoom && !canUploadInPublic) {
        toast.error("Photo and file uploads in public chat are restricted to Admin and Moderators.")
        setChatAttachment(null)
        setChatLoading(false)
        return
      }

      // Play notification sound on submit!
      playNotificationSound("Messenger")

      // Optimistic real-time insert like Messenger (0ms latency feeling)
      const optimisticId = `temp_${Date.now()}`
      const optimisticMsg = {
        id: optimisticId,
        channel: chatChannel,
        email: senderEmail,
        username: senderUsername,
        text,
        timestamp: Date.now(),
        role: senderRole as any,
        replyTo: chatReplyTo ? { id: chatReplyTo.id, username: chatReplyTo.username, text: chatReplyTo.text } : undefined,
        attachment: attachmentToSend || undefined,
      }
      setChatMessages((prev) => [...prev, optimisticMsg])
      const sentReplyTo = chatReplyTo
      const sentAttachment = attachmentToSend
      setChatInputText("")
      setChatReplyTo(null)
      setChatAttachment(null)
      setShowEmojiPicker(false)
      if (chatFileInputRef.current) chatFileInputRef.current.value = ""

      // Normal send with replyTo & attachment support
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "send",
          channel: chatChannel,
          email: senderEmail,
          username: senderUsername,
          isAdmin: isMaster,
          passcode: isMaster ? "b3933c5b836dea05907e15eacca2ec803eaee641fb3c11b39decc19dfba3767a" : undefined,
          text,
          replyTo: sentReplyTo ? { id: sentReplyTo.id, username: sentReplyTo.username, text: sentReplyTo.text } : undefined,
          attachment: sentAttachment || undefined,
        }),
      })
      const data = (await res.json().catch(() => ({}))) as { success?: boolean; error?: string; botReply?: any; muted?: boolean; mutedUntil?: number }
      if (res.ok && data.success) {
        const confirmedMsg = (data as any).message ? {
          ...(data as any).message,
          channel: normalizeChatChannel((data as any).message.channel || chatChannel),
        } : null

        setChatMessages((prev) => {
          let next = prev.filter((m) => m.id !== optimisticId)
          if (confirmedMsg) {
            next = next.filter((m) => m.id !== confirmedMsg.id)
            next.push(confirmedMsg)
          }
          if (data.botReply) {
            const confirmedBot = {
              ...data.botReply,
              channel: normalizeChatChannel(data.botReply.channel || chatChannel),
            }
            next = next.filter((m) => m.id !== confirmedBot.id)
            next.push(confirmedBot)
          }
          next.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0))
          try {
            safeStorage.setItem("ast_chat_messages_cache_v3", JSON.stringify(next.slice(-800)))
          } catch {}
          return next
        })

        if (data.botReply) {
          setTimeout(() => playNotificationSound("Messenger"), 200)
        }
        void fetchChatMessages(chatChannel)
      } else {
        setChatMessages((prev) => {
          const filtered = prev.filter((m) => m.id !== optimisticId)
          try { safeStorage.setItem("ast_chat_messages_cache_v3", JSON.stringify(filtered.slice(-800))) } catch {}
          return filtered
        })
        toast.error(data.error || "Failed to deliver message.")
      }
    } catch {
      toast.error("Network error sending message.")
    } finally {
      setChatLoading(false)
    }
  }

