  const handleSendDirectMessage = async (targetEmail?: string, targetUsername?: string, textCustom?: string, categoryCustom?: string) => {
    const textToSend = (textCustom || directMsgText || adminMsgText).trim()
    const target = (targetEmail || (selectedChatUser ? selectedChatUser.email : "astrxy@beezelbub.com")).toLowerCase().trim()
    const targetName = targetUsername || (selectedChatUser ? selectedChatUser.username : (target === "astrxy@beezelbub.com" ? "JoyBoy (Founder)" : target.split("@")[0]))
    const isTargetAdmin = target === "astrxy@beezelbub.com"

    if (!textToSend) {
      toast.error(isTargetAdmin ? "Please enter a message for Master Admin." : `Please enter a message for @${targetName}.`)
      return
    }

    setIsSendingAdminMsg(true)
    try {
      const currentActive = (activeEmail || "").toLowerCase().trim()
      const isActualAdmin = Boolean(isUserAdmin || chatAdminUnlocked || currentActive === "astrxy@beezelbub.com")
      const senderEmail = isActualAdmin ? "astrxy@beezelbub.com" : (currentActive || chatClaimedEmail || "visitor").trim().toLowerCase()
      const curMods = getModeratorsList()
      const isActualMod = curMods.includes(senderEmail) || chatModeratorList.includes(senderEmail)

      const isEmailClaimed = claimed && (claimedAddress.toLowerCase().trim() === senderEmail)
      const localClaims = readClaimedKeys()
      const isLocalClaimed = Object.values(localClaims).some((c) => c.toLowerCase().trim() === senderEmail)
      const isActuallyClaimed = isEmailClaimed || isLocalClaimed
      const senderRole = isActualAdmin ? "admin" : isActualMod ? "moderator" : isActuallyClaimed ? "claimed" : "visitor"
      const senderUsername = chatUsername || (isActualAdmin ? "astrxy" : (senderEmail && senderEmail.includes("@") ? senderEmail.split("@")[0] : "Visitor"))

      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "direct_message",
          channel: chatChannel || "visitor",
          email: senderEmail,
          username: senderUsername,
          role: senderRole,
          text: textToSend,
          category: categoryCustom || directMsgCategory || adminMsgCategory || "💬 Direct Message",
          targetEmail: target,
          targetUsername: targetName,
        }),
      })
      const data = (await res.json().catch(() => ({}))) as { success?: boolean; error?: string; entry?: any }
      if (res.ok && data.success) {
        toast.success(isTargetAdmin ? "✓ Message dispatched to Master Admin across all servers!" : `✓ Direct message delivered to @${targetName}'s Inbox!`)
        if (data.entry) {
          setUserInboxList((prev) => [data.entry, ...prev.filter((m) => m.id !== data.entry.id)])
          if (isActualAdmin) {
            setAdminInboxList((prev) => [data.entry, ...prev.filter((m) => m.id !== data.entry.id)])
          }
        }
        setDirectMsgText("")
        setAdminMsgText("")
        setInboxReplyOpenId(null)
        setInboxReplyText("")
        void fetchChatMessages(chatChannel)
      } else {
        toast.error(data.error || `Failed to send direct message to @${targetName}.`)
      }
    } catch (err: any) {
      console.error("handleSendDirectMessage error:", err)
      toast.error(err?.message ? `Error: ${err.message}` : "Network error sending direct message.")
    } finally {
      setIsSendingAdminMsg(false)
      setIsSendingDirectReply(false)
    }
  }

