        const query = searchQuery.toLowerCase().trim()
        const matchSender = msg.sender.toLowerCase().includes(query) || (msg.senderName && msg.senderName.toLowerCase().includes(query))
        const matchSubject = msg.subject.toLowerCase().includes(query)
        const matchBody = msg.body.toLowerCase().includes(query)
        const matchOtp = msg.otpCode && msg.otpCode.includes(query)
        return matchSender || matchSubject || matchBody || matchOtp
