                          S: { bg: "rgba(234, 179, 8, 0.2)", text: "#fde047", border: "rgba(234, 179, 8, 0.4)" },
                          SS: { bg: "rgba(168, 85, 247, 0.2)", text: "#d8b4fe", border: "rgba(168, 85, 247, 0.4)" },
