                        const activeClassObj = towerClass ? TOWER_CLASSES[towerClass] : null
                        const isMasterAdmin = Boolean(isUserAdmin || chatAdminUnlocked || (activeEmail || chatClaimedEmail || "").toLowerCase().trim() === "astrxy@beezelbub.com")

                        // Currency formatter (supports K, M, B)
                        const fmtCur = (num: number): string => {
                          if (num >= 1000000000) return `${(num / 1000000000).toFixed(num % 1000000000 === 0 ? 0 : 2)}B`
                          if (num >= 1000000) return `${(num / 1000000).toFixed(num % 1000000 === 0 ? 0 : 1)}M`
                          if (num >= 1000) return `${(num / 1000).toFixed(num % 1000 === 0 ? 0 : 1)}K`
                          return num.toLocaleString()
                        }

